"""Frozen media manifests; generated bytes are disposable, never silently replaced."""

from __future__ import annotations

import hashlib
import json
import os
import tempfile
from pathlib import Path

from ironsbot.core.outbound import BinaryImagePart, OutboundMessage, RemoteImagePart


def encode_media(message: OutboundMessage | None, root: Path) -> str:
    entries = []
    for part in message.parts if message else ():
        if isinstance(part, RemoteImagePart):
            entries.append({"url": part.url})
        elif isinstance(part, BinaryImagePart):
            digest = hashlib.sha256(part.content).hexdigest()
            root.mkdir(parents=True, exist_ok=True)
            path = root / digest
            # Concurrent writers store identical content-addressed bytes.
            if not path.exists():
                descriptor, raw_temporary = tempfile.mkstemp(dir=root, prefix=".media-")
                temporary = Path(raw_temporary)
                try:
                    with os.fdopen(descriptor, "wb") as stream:
                        stream.write(part.content)
                    temporary.replace(path)
                finally:
                    temporary.unlink(missing_ok=True)
            entries.append(
                {
                    "sha256": digest,
                    "content_type": part.content_type,
                    "filename": part.filename,
                }
            )
    return json.dumps(entries, sort_keys=True)


def decode_media(payload: str, root: Path) -> OutboundMessage | None:
    parts = []
    for entry in json.loads(payload):
        if "url" in entry:
            parts.append(RemoteImagePart(entry["url"]))
            continue
        digest = entry["sha256"]
        if len(digest) != hashlib.sha256().digest_size * 2 or any(
            char not in "0123456789abcdef" for char in digest
        ):
            msg = "Invalid frozen media fingerprint"
            raise ValueError(msg)
        content = (root / digest).read_bytes()
        if hashlib.sha256(content).hexdigest() != digest:
            msg = "Frozen media fingerprint mismatch"
            raise ValueError(msg)
        parts.append(BinaryImagePart(content, entry["content_type"], entry["filename"]))
    return OutboundMessage(tuple(parts)) if parts else None
